// Ejemplo con driver oficial; session proviene de client.startSession().
const session = client.startSession();
try {
  session.startTransaction();
  await db.collection('pedidos').insertOne({ productoId: 7, cantidad: 1 }, { session });
  await db.collection('productos').updateOne({ _id: 7 }, { $inc: { stock: -1 } }, { session });
  await session.commitTransaction();
} catch (error) {
  await session.abortTransaction();
  throw error;
} finally { await session.endSession(); }

// El callback debe evitar efectos externos irreversibles.
const session = client.startSession();
try {
  await session.withTransaction(async () => {
    await db.collection('auditoria').insertOne({ evento: 'pago' }, { session });
    await db.collection('pedidos').updateOne({ _id: 10 }, { $set: { pagado: true } }, { session });
  });
} finally { await session.endSession(); }

