export async function listarNovelas(db) {
  return db.collection('novelas').find({ publicada: true }, { projection: { titulo: 1, slug: 1 } }).limit(50).toArray();
}

// routes/novelas.js
import { Router } from 'express';
import { listarNovelas } from '../repositories/novelas.js';
const router = Router();
router.get('/novelas', async (req, res) => {
  const novelas = await listarNovelas(req.app.locals.db);
  res.json(novelas);
});
export default router;

